import React, { useState } from "react";
import { Box, Typography, Grid, Card, CardContent, Button, Radio, RadioGroup, FormControlLabel } from "@mui/material";

const positions = [
  {
    title: "Position 1",
    candidates: [
      { id: "1a", name: "Candidate 1a", image: "https://via.placeholder.com/100", manifestoLink: "#" },
      { id: "1b", name: "Candidate 1b", image: "https://via.placeholder.com/100", manifestoLink: "#" },
      { id: "1c", name: "Candidate 1c", image: "https://via.placeholder.com/100", manifestoLink: "#" },
    ],
  },
  {
    title: "Position 2",
    candidates: [
      { id: "2a", name: "Candidate 2a", image: "https://via.placeholder.com/100", manifestoLink: "#" },
      { id: "2b", name: "Candidate 2b", image: "https://via.placeholder.com/100", manifestoLink: "#" },
      { id: "2c", name: "Candidate 2c", image: "https://via.placeholder.com/100", manifestoLink: "#" },
      { id: "2d", name: "Candidate 2d", image: "https://via.placeholder.com/100", manifestoLink: "#" },
    ],
  },
];

const VotingPage = () => {
  const [selectedVotes, setSelectedVotes] = useState({});

  const handleVoteChange = (position, candidateId) => {
    setSelectedVotes((prev) => ({ ...prev, [position]: candidateId }));
  };

  const handleConfirmVote = () => {
    console.log("Votes submitted:", selectedVotes);
    alert("Your votes have been submitted successfully!");
  };

  return (
    <Box sx={{ textAlign: "center", p: 3 }}>
      <Typography variant="h4" fontWeight="bold" mb={3}>
        Cast Your Vote
      </Typography>
      
      {positions.map((position) => (
        <Box key={position.title} sx={{ mb: 4 }}>
          <Typography variant="h5" fontWeight="bold" sx={{ mb: 2 }}>
            {position.title}
          </Typography>

          <RadioGroup row value={selectedVotes[position.title] || ""} onChange={(e) => handleVoteChange(position.title, e.target.value)}>
            <Grid container spacing={2} justifyContent="center">
              {position.candidates.map((candidate) => (
                <Grid item key={candidate.id}>
                  <Card sx={{ width: 150, textAlign: "center", p: 2 }}>
                    <img src={candidate.image} alt={candidate.name} width="100" height="100" style={{ borderRadius: "5px" }} />
                    <CardContent>
                      <Typography variant="body1" fontWeight="bold">{candidate.name}</Typography>
                      <FormControlLabel value={candidate.id} control={<Radio />} label="" />
                      <Button variant="outlined" size="small" href={candidate.manifestoLink} target="_blank" sx={{ mt: 1 }}>
                        Manifesto
                      </Button>
                    </CardContent>
                  </Card>
                </Grid>
              ))}
            </Grid>
          </RadioGroup>
        </Box>
      ))}

      <Button variant="contained" color="primary" onClick={handleConfirmVote} sx={{ mt: 3 }}>
        Confirm Vote
      </Button>
    </Box>
  );
};

export default VotingPage;
